messages.text:
The NPC: Also: when thirsty, Mira drinks at the well before anything but going home.

The storyboard's entries about it:
{"character/mira":{"name":"Mira","summary":"Sells fruit from her stall in the square. When she runs out she picks more in the orchard, and she goes home at night."}}

Entity IDs a go_to may walk to: ["home","orchard","stall","well"]
Events the game's code answers, which an emit may use: ["sell"]

Revise this brain, keeping what the brief doesn't change:
{
  "actions": [
    {
      "do": {
        "go_to": "orchard"
      },
      "effects": {
        "at_home": false,
        "at_orchard": true,
        "at_stall": false
      },
      "name": "walk_to_orchard"
    },
    {
      "cost": 2,
      "do": {
        "wait": 2
      },
      "effects": {
        "fruit": "+3"
      },
      "name": "pick_fruit",
      "needs": {
        "at_orchard": true
      }
    },
    {
      "do": {
        "go_to": "stall"
      },
      "effects": {
        "at_home": false,
        "at_orchard": false,
        "at_stall": true
      },
      "name": "walk_to_stall"
    },
    {
      "do": {
        "emit": "sell"
      },
      "effects": {
        "customers": "-1",
        "fruit": "-1"
      },
      "name": "sell_fruit",
      "needs": {
        "at_stall": true,
        "customers": ">0",
        "fruit": ">0"
      }
    },
    {
      "do": {
        "go_to": "home"
      },
      "effects": {
        "at_home": true,
        "at_orchard": false,
        "at_stall": false
      },
      "name": "walk_home"
    }
  ],
  "facts": {
    "at_home": false,
    "at_orchard": false,
    "at_stall": false,
    "customers": 0,
    "fruit": 0,
    "night": false
  },
  "format": 1,
  "goals": [
    {
      "name": "sleep",
      "priority": 3,
      "want": {
        "at_home": true
      },
      "when": {
        "night": true
      }
    },
    {
      "name": "restock",
      "priority": 2,
      "want": {
        "fruit": ">=3"
      },
      "when": {
        "fruit": 0
      }
    },
    {
      "name": "serve",
      "priority": 1,
      "want": {
        "customers": 0
      },
      "when": {
        "customers": ">0"
      }
    },
    {
      "name": "mind_stall",
      "want": {
        "at_stall": true
      }
    }
  ]
}


